from scipy.optimize import minimize

def objective(x):
    S = np.sum(x)
    return (np.sum(x**2) + S**2 - 20)**2

def constraint_S(x):
    return 1 - abs(np.sum(x))

def constraint_x(x):
    return 1 - np.abs(x)

n = 20
x0 = np.random.uniform(-1, 1, n)
cons = [{'type': 'ineq', 'fun': constraint_S},
        {'type': 'ineq', 'fun': lambda x: constraint_x(x)}]

res = minimize(objective, x0, constraints=cons, method='SLSQP')
print(f"n=20: res.fun={res.fun}, x={res.x}, S={np.sum(res.x)}, sum_x2={np.sum(res.x**2)}")

import numpy as np
from scipy.optimize import minimize

def objective(x):
    S = np.sum(x)
    return (np.sum(x**2) + S**2 - 20)**2

def constraint_S(x):
    return 1 - abs(np.sum(x))

def constraint_x(x):
    return 1 - np.abs(x)

def solve_for_n(n):
    x0 = np.random.uniform(-1, 1, n)
    cons = [{'type': 'ineq', 'fun': constraint_S},
            {'type': 'ineq', 'fun': lambda x: constraint_x(x)}]
    res = minimize(objective, x0, constraints=cons, method='SLSQP')
    return res

for n in [20, 21]:
    res = solve_for_n(n)
    print(f"n={n}: objective={res.fun}, S={np.sum(res.x)}, sum_x2={np.sum(res.x**2)}, max_x={np.max(np.abs(res.x))}")
